{
    const uint64_t            sec     = 1'000'000'000ULL;
    std::vector<timer_sample> samples = {
        make_sample(0, 0 * sec, 1 * sec, { "A" }),
        make_sample(0, 1 * sec, 2 * sec, { "A", "B" }),
        make_sample(0, 2 * sec, 3 * sec, { "A", "B", "C" }),
    };

    std::ostringstream   w, c, p, t;
    native_report_writer wr(w, c, p, t);
    wr.write_timer_samples(0, samples);
    wr.flush();
    EXPECT_EQ(p.str(), k_w2_pct)
        << "W2 percent TSV must match golden byte-for-byte (NFR-T-7)";
}

