// ── W8: flat_scope fib dedup ─────────────────────────────────────────────────

TEST(native_report_writer_golden, w8_wall_clock_byte_exact)
{
    const uint64_t           sec    = 1'000'000'000ULL;
    std::vector<std::string> stack5 = { "a", "b", "c", "d", "e", "fib" };
    std::vector<std::string> stack6 = { "a", "b", "c", "d", "e", "f", "fib" };

    std::ostringstream   w, c, p, t;
    native_report_writer wr(w, c, p, t);
    wr.write_timer_samples(0, {
                                  make_sample(0, 0 * sec, 1 * sec, stack5),
                                  make_sample(0, 1 * sec, 2 * sec, stack6),
                              });
    wr.flush();
    EXPECT_EQ(w.str(), k_w8_wall)
        << "W8 wall_clock TSV must match golden byte-for-byte (NFR-T-7)";
}

